  "title": "expose-observation-type-on-wrapper",
  "request": "Can we add an attribute to the wrapped function so we can introspect which observation type was used? I'd like the wrapper returned by @observe to have a ._langfuse_as_type attribute reflecting the normalized type (defaulting to "span").",
  "edits": [
    {
      "path": "langfuse/_client/observe.py",
      "search": "return cast(F, async_wrapper)",
      "replace": "                async_wrapper._langfuse_as_type = as_type or "span"
                return cast(F, async_wrapper)"
    },
    {
      "path": "langfuse/_client/observe.py",
      "search": "return cast(F, sync_wrapper)",
      "replace": "                sync_wrapper._langfuse_as_type = as_type or "span"
                return cast(F, sync_wrapper)"
    }
