  "test_path": "tests/unit/test_observe_as_type_attribute.py",
  "test": "import pytest
from langfuse import observe

def test_observe_wrapper_has_as_type_attribute():
    @observe(as_type="generation")
    def foo() -> None:
        pass

    assert hasattr(foo, "_langfuse_as_type")
    assert foo._langfuse_as_type == "generation"

def test_observe_invalid_as_type_defaults_to_span():
    @observe(as_type="invalid_type")
    def bar() -> None:
        pass

    assert hasattr(bar, "_langfuse_as_type")
    assert bar._langfuse_as_type == "span"
